      "title": "El rumor de las máquinas",
      "tematica": "lavanderia",
      "tematicaLabel": "La lavandería",
      "personajes": "Daniel (38, periodista) · Elena (35, diseñadora gráfica)",
      "registro": "Literario",
      "registroFull": "Literario",
      "formato": "Corto",
      "formatoFull": "Relato corto autoconclusivo",
